<?php
declare(strict_types=1);

require_once __DIR__ . '/../includes/bootstrap.php';

require_role('id_admin', '1', '../admin-login.php');

$pdo = app_pdo();
$theme = current_theme();
$professionalId = request_query_int('id_professional');
$profesional = fetch_one($pdo->prepare('SELECT * FROM professionals WHERE id_professional = :id'), array(':id' => $professionalId));
$disciplinas = fetch_all($pdo->prepare('SELECT * FROM disciplinas ORDER BY nombre_disciplina'));

if ($profesional === null) {
    app_redirect('../admin-dashboard.php#equipo', 'Profesional no encontrado');
}
?>
<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Editar profesional</title><script src="https://cdn.tailwindcss.com"></script><style>:root{--primary:<?php echo escape_html($theme['primary']); ?>;--secondary:<?php echo escape_html($theme['secondary']); ?>;}body{background:linear-gradient(180deg,#f8fafc 0%,#edf2f7 100%);}</style></head><body class="min-h-screen px-4 py-8 text-slate-900 sm:px-6"><main class="mx-auto max-w-4xl rounded-[2rem] border border-white/50 bg-white/85 p-6 shadow-2xl backdrop-blur-xl sm:p-8"><a class="text-sm font-medium text-slate-500 hover:text-slate-900" href="../admin-dashboard.php#equipo">← Volver</a><h1 class="mt-4 text-3xl font-semibold">Editar profesional</h1><form action="update.php?id_professional=<?php echo escape_html((string) $profesional['id_professional']); ?>&accion=profesional" method="post" class="mt-6 grid gap-4 sm:grid-cols-2"><label class="block text-sm font-medium text-slate-600">Nombre<input class="mt-2 w-full rounded-2xl border border-slate-200 px-4 py-3" name="name_professional" value="<?php echo escape_html($profesional['name_professional']); ?>" required></label><label class="block text-sm font-medium text-slate-600">Usuario<input class="mt-2 w-full rounded-2xl border border-slate-200 px-4 py-3" name="user_professional" value="<?php echo escape_html($profesional['user_professional']); ?>" required></label><label class="block text-sm font-medium text-slate-600">Correo<input class="mt-2 w-full rounded-2xl border border-slate-200 px-4 py-3" name="email_professional" type="email" value="<?php echo escape_html($profesional['email_professional']); ?>" required></label><label class="block text-sm font-medium text-slate-600">Teléfono<input class="mt-2 w-full rounded-2xl border border-slate-200 px-4 py-3" name="phone_professional" value="<?php echo escape_html($profesional['phone_professional']); ?>" required></label><label class="block text-sm font-medium text-slate-600">Disciplina<select class="mt-2 w-full rounded-2xl border border-slate-200 px-4 py-3" name="id_disciplina"><option value="">General</option><?php foreach ($disciplinas as $disciplina): ?><option value="<?php echo escape_html((string) $disciplina['id_disciplina']); ?>" <?php echo (int) ($profesional['id_disciplina'] ?? 0) === (int) $disciplina['id_disciplina'] ? 'selected' : ''; ?>><?php echo escape_html($disciplina['nombre_disciplina']); ?></option><?php endforeach; ?></select></label><label class="block text-sm font-medium text-slate-600">Color<input class="mt-2 h-12 w-full rounded-2xl border border-slate-200 px-2 py-2" name="calendar_color" type="color" value="<?php echo escape_html($profesional['calendar_color']); ?>" required></label><label class="block text-sm font-medium text-slate-600">Nueva contraseña<input class="mt-2 w-full rounded-2xl border border-slate-200 px-4 py-3" name="pass_professional" type="password" minlength="8"></label><label class="block text-sm font-medium text-slate-600">Activo<select class="mt-2 w-full rounded-2xl border border-slate-200 px-4 py-3" name="activo"><option value="1" <?php echo (int) $profesional['activo'] === 1 ? 'selected' : ''; ?>>Sí</option><option value="0" <?php echo (int) $profesional['activo'] === 0 ? 'selected' : ''; ?>>No</option></select></label><label class="block text-sm font-medium text-slate-600 sm:col-span-2">Bio<textarea class="mt-2 min-h-24 w-full rounded-2xl border border-slate-200 px-4 py-3" name="bio_professional"><?php echo escape_html($profesional['bio_professional']); ?></textarea></label><button class="sm:col-span-2 inline-flex items-center justify-center rounded-2xl px-6 py-3 text-sm font-semibold text-white shadow-lg" style="background:linear-gradient(135deg,var(--secondary),var(--primary));" type="submit">Guardar cambios</button></form></main></body></html>
